from fractions import Fraction

def rref(M, cols):
    R = [[Fraction(x) for x in row] for row in M]
    pivots = []
    for c in range(cols):
        r = len(pivots)
        p = r
        while p < len(R) and R[p][c] == 0:
            p = p + 1
        if p == len(R):
            continue
        R[r], R[p] = R[p], R[r]
        k = R[r][c]
        R[r] = [x / k for x in R[r]]
        for i in range(len(R)):
            k = R[i][c]
            if i != r and k != 0:
                R[i] = [R[i][j] - k * R[r][j] for j in range(len(R[i]))]
        pivots.append(c)
    return R, pivots

def show(M):
    return "  ".join("[" + ", ".join(str(x) for x in row) + "]" for row in M)

def vec(v):
    return "(" + ", ".join(str(x) for x in v) + ")"

def special(R, pivots, n):
    result = []
    for f in [j for j in range(n) if j not in pivots]:
        s = [Fraction(0)] * n
        s[f] = Fraction(1)
        for i in range(len(pivots)):
            s[pivots[i]] = -R[i][f]
        result.append(s)
    return result

def eigenspace(A, lam):
    n = len(A)
    M = [[A[i][j] - (lam if i == j else 0) for j in range(n)] for i in range(n)]
    R, pivots = rref(M, n)
    return special(R, pivots, n)

def dot(u, v):
    return sum(u[i] * v[i] for i in range(len(u)))

def gram_schmidt(xs):
    vs = []
    for x in xs:
        v = list(x)
        for u in vs:
            c = dot(x, u) / dot(u, u)
            v = [v[i] - c * u[i] for i in range(len(v))]
        vs.append(v)
    return vs

def spectral(A, lams):
    n = len(A)
    if A != [[A[j][i] for j in range(n)] for i in range(n)]:
        print("  not symmetric")
        return
    vs = []
    for lam in lams:
        fixed = gram_schmidt(eigenspace(A, lam))
        print(f"  lambda = {lam}: {', '.join(vec(v) for v in fixed)}")
        vs = vs + fixed
    ok = all(dot(vs[i], vs[j]) == 0 for i in range(len(vs)) for j in range(i + 1, len(vs)))
    print(f"  all pairs orthogonal: {ok}")

