from fractions import Fraction

def classify(a, b, c):
    h = b / 2
    det = a * c - h * h
    print(f"  A = [{a}, {h}], [{h}, {c}], det {det}")
    if det > 0:
        print("  positive definite" if a > 0 else "  negative definite")
    elif det < 0:
        print("  indefinite")
    elif a + c > 0:
        print("  positive semidefinite")
    elif a + c < 0:
        print("  negative semidefinite")
    else:
        print("  zero")

k = int(input())
for t in range(k):
    a, b, c = [Fraction(w) for w in input().split()]
    print(f"q = ({a})x^2 + ({b})xy + ({c})y^2")
    classify(a, b, c)
